document.addEventListener('DOMContentLoaded',function(){const searchInput=document.getElementById('paper-search');const mobileSearchToggle=document.querySelector('.mobile-search-toggle');const searchContainer=document.getElementById('searchContainer');const searchDropdown=document.getElementById('searchDropdown');const backNavContainer=document.getElementById('backNavContainer');const backButton=document.getElementById('backButton');const backButtonText=document.getElementById('backButtonText');const patternSelects=document.querySelectorAll('.pattern-select');patternSelects.forEach((select)=>{select.addEventListener('change',function(){if(this.value&&this.value!==window.location.pathname){window.location.href=this.value;}});});if(mobileSearchToggle){mobileSearchToggle.addEventListener('click',()=>{searchContainer.classList.toggle('active');mobileSearchToggle.classList.toggle('active');if(searchContainer.classList.contains('active')){searchInput.focus();}});}
let searchData=[];let activeIndex=-1;fetch('/static/search.1.json').then(res=>res.json()).then(data=>{searchData=data;}).catch(()=>{console.warn('Failed to load search index');});function scoreMatch(item,query){const sn=item.subject_name.toLowerCase();const bn=item.branch_name.toLowerCase();const bc=item.branch_code.toLowerCase();const sl=item.subject_link.toLowerCase();const kw=item.keywords.toLowerCase();const abbr=(item.abbreviation||"").toLowerCase();let score=0;if(sn===query){score=100;}else if(sn.startsWith(query)){score=80;}else if(abbr===query){score=75;}else if(new RegExp('\\b'+query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).test(sn)){score=70;}else if(sn.includes(query)){score=60;}
if(abbr&&abbr!==query&&abbr.startsWith(query)){score+=15;}
if(kw.includes(query)){score+=20;}
if(bn.includes(query)){score+=5;}
if(bc.includes(query)){score+=3;}
if(sl.includes(query)){score+=3;}
return score;}
searchInput.addEventListener('input',function(){const query=this.value.trim().toLowerCase();if(query.length<2){searchDropdown.style.display='none';searchDropdown.innerHTML='';activeIndex=-1;return;}
const scored=[];for(const item of searchData){const score=scoreMatch(item,query);if(score>0){scored.push({item,score});}}
scored.sort((a,b)=>b.score-a.score);const results=scored.slice(0,10);searchDropdown.innerHTML='';activeIndex=-1;if(!results.length){searchDropdown.innerHTML='<div class="search-no-results">No results found</div>';searchDropdown.style.display='block';return;}
results.forEach((entry,idx)=>{const item=entry.item;const row=document.createElement('div');row.classList.add('search-result-row');const meta=item.sem_no?`${item.branch_name} &mdash; Sem ${item.sem_no}`:`${item.branch_name}${item.year_label ? ' &mdash; ' + item.year_label : ''}`;row.innerHTML=`
                <span class="result-subject">${item.subject_name}</span>
                <span class="result-branch">${meta}</span>
            `;row.addEventListener('click',()=>{window.location.href=item.public_url||('/'+item.subject_link);});row.addEventListener('mouseenter',()=>{activeIndex=idx;updateActiveRow();});searchDropdown.appendChild(row);});searchDropdown.style.display='block';});searchInput.addEventListener('keydown',function(e){const rows=searchDropdown.querySelectorAll('.search-result-row');if(!rows.length)return;if(e.key==='ArrowDown'){e.preventDefault();activeIndex=(activeIndex+1)%rows.length;updateActiveRow();}else if(e.key==='ArrowUp'){e.preventDefault();activeIndex=activeIndex<=0?rows.length-1:activeIndex-1;updateActiveRow();}else if(e.key==='Enter'&&activeIndex>=0){e.preventDefault();rows[activeIndex].click();}});function updateActiveRow(){const rows=searchDropdown.querySelectorAll('.search-result-row');rows.forEach((row,i)=>{row.classList.toggle('active',i===activeIndex);});}
document.addEventListener('click',function(e){if(!searchContainer.contains(e.target)){searchDropdown.style.display='none';}});searchInput.addEventListener('focus',function(){if(searchDropdown.children.length){searchDropdown.style.display='block';}});function updateSearchBarVisibility(){if(window.innerWidth>=900){searchContainer.classList.add('active');searchContainer.style.display='flex';}else if(!searchContainer.classList.contains('active')){searchContainer.style.display='';}}
updateSearchBarVisibility();window.addEventListener('resize',updateSearchBarVisibility);function clearActive(){document.querySelectorAll('.nav-level').forEach(el=>el.classList.remove('active'));}
function updateBackNavigation(path){if(!backNavContainer||!backButton||!backButtonText)return;if(path.length<2){backNavContainer.hidden=true;return;}
backNavContainer.hidden=false;const parent=path[path.length-2];backButtonText.textContent=`Back to ${parent.name}`;backButton.onclick=()=>showLevel(parent.target_id);}
window.showLevel=function(levelId){clearActive();const level=document.getElementById(levelId);if(!level)return;level.classList.add('active');let path=[];try{path=JSON.parse(level.getAttribute('data-breadcrumbs')||'[]');}catch(_error){path=[];}
updateBackNavigation(path);window.scrollTo({top:0,behavior:'smooth'});};window.showBranches=function(){showLevel('root');};updateBackNavigation([]);function setupCustomDropdown(dropdownId,selectedId,optionsId){const dropdown=document.getElementById(dropdownId);const selected=document.getElementById(selectedId);const optionsContainer=document.getElementById(optionsId);if(!dropdown||!selected||!optionsContainer)return;selected.addEventListener('click',(e)=>{e.stopPropagation();optionsContainer.classList.toggle('show');selected.classList.toggle('open');});const options=optionsContainer.querySelectorAll('.dropdown-option');options.forEach(opt=>{opt.addEventListener('click',(e)=>{e.stopPropagation();const val=opt.getAttribute('data-value');if(val&&val!==window.location.pathname){window.location.href=val;}else{optionsContainer.classList.remove('show');selected.classList.remove('open');}});});}
setupCustomDropdown('customPatternDropdown','dropdownSelected','dropdownOptions');setupCustomDropdown('mobilePatternDropdown','mobileDropdownSelected','mobileDropdownOptions');document.addEventListener('click',()=>{document.querySelectorAll('.dropdown-options.show').forEach(el=>el.classList.remove('show'));document.querySelectorAll('.dropdown-selected.open').forEach(el=>el.classList.remove('open'));});});
